'use strict';
let publicData=null,venueData=null,venuePage=0,licensedSnapshot=null;
const activity=[],countries=new Intl.DisplayNames(['en'],{type:'region'});
const countryName=code=>{try{return countries.of(code)||code}catch{return code}};
const ageDays=date=>(Date.now()-Date.parse(date))/86400000;
const stale=feed=>feed.asOf&&ageDays(feed.asOf)>7;
const fnum=(n,d=2)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
function logActivity(action,details){activity.unshift({at:new Date().toISOString(),action,details});if(activity.length>100)activity.pop();renderEvidence();}
async function api(path,options={}){const response=await fetch(path,{...options,signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data;}
function sourceCard(title,value,feed,note){const ok=feed?.status==='available';return `<article class="card metric"><label>${title}</label><strong class="${!ok||stale(feed)?'warn':''}">${ok?value:'Unavailable'}</strong><small>${ok?'Observation: '+esc(feed.asOf):'Source retrieval failed'}</small><span class="data-source">${esc(feed?.source||'')} · ${ok&&stale(feed)?'STALE OBSERVATION':ok?'Published data':'No replacement data'}</span><p class="notice">${esc(note)}</p></article>`;}
function chart(history,key){
  if(!history?.length)return '<p class="notice">No observations available.</p>';
  const values=history.map(r=>r[key]),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1;
  const x=i=>30+i/(Math.max(1,values.length-1))*640,y=v=>190-(v-min)/span*160;
  const points=values.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
  return `<svg viewBox="0 0 700 220" role="img" aria-label="OFR Financial Stress Index, ${esc(history[0].date)} through ${esc(history.at(-1).date)}. Latest ${values.at(-1)}."><line x1="30" x2="680" y1="${y(0)}" y2="${y(0)}" stroke="#537187" stroke-dasharray="4 4"/><text x="5" y="${y(0)+4}" fill="#a5b5c8" font-size="12">0</text><text x="30" y="18" fill="#a5b5c8" font-size="12">${fnum(max)}</text><text x="30" y="213" fill="#a5b5c8" font-size="12">${fnum(min)}</text><polyline points="${points}" fill="none" stroke="#64e3bd" stroke-width="2.5"/><circle cx="670" cy="${y(values.at(-1))}" r="4" fill="#64e3bd"/></svg><div class="axis"><span>${history[0].date}</span><span>${history.at(-1).date}</span></div>`;
}
function renderPublic(){
  const {fsi,sofr,fx}=publicData.feeds;
  $('publicMetrics').innerHTML=sourceCard('Global financial stress',fsi.status==='available'?fnum(fsi.latest['OFR FSI']):'',fsi,'OFR FSI; positive values indicate above-average stress.')+sourceCard('Secured overnight funding',sofr.status==='available'?fnum(sofr.latest.rate)+'%':'',sofr,'SOFR; secured USD overnight funding benchmark.')+sourceCard('EUR / USD reference',fx.status==='available'?fnum(fx.rates.USD,4):'',fx,'ECB reference rate, not an executable quote.');
  const brief=[];
  if(fsi.status==='available'){
    const latest=fsi.latest['OFR FSI'],delta=latest-fsi.previous['OFR FSI'];
    brief.push(`OFR stress is ${latest>=0?'above':'below'} its historical average at ${fnum(latest)}. It ${delta>=0?'rose':'fell'} ${fnum(Math.abs(delta),3)} index points since the previous published observation.`);
    $('fsiChart').innerHTML=chart(fsi.history,'OFR FSI');
    const keys=['Credit','Equity valuation','Safe assets','Funding','Volatility','United States','Other advanced economies','Emerging markets'];
    $('fsiComponents').innerHTML='<div class="allocation-key">'+keys.map(k=>`<div><span>${k}</span><b class="${fsi.latest[k]>0?'warn':'up'}">${fnum(fsi.latest[k],3)}</b></div>`).join('')+'</div><p class="notice">First five rows decompose stress by category; last three decompose it by region. Do not add both decompositions together.</p>';
  }else{$('fsiChart').innerHTML='<p class="notice">OFR data unavailable.</p>';$('fsiComponents').textContent='No component data available.';}
  if(sofr.status==='available')brief.push(`SOFR changed ${fnum((sofr.latest.rate-sofr.previous.rate)*100,1)} basis points since the previous observation. Reported transaction volume is $${fnum(sofr.latest.volumeBillions,0)} billion.`);
  for(const [id,feed] of Object.entries(publicData.feeds))if(feed.status!=='available'||stale(feed))brief.push(`${feed.source}: ${feed.status!=='available'?'retrieval failed; do not infer a current value':'observation is older than seven calendar days; review publication availability'}.`);
  $('systemBrief').innerHTML=brief.map(t=>'<p class="notice">'+esc(t)+'</p>').join('')+'<p class="public-note">These indicators support review. They do not establish causation, forecast returns, or constitute a systemic-risk certification.</p>';
  $('fxTable').innerHTML=fx.status==='available'?'<div class="allocation-key">'+Object.entries(fx.rates).filter(([c])=>c!=='EUR').map(([c,r])=>`<div><span>${c}</span><b>${fnum(r,4)}</b></div>`).join('')+'</div>':'<p class="notice">ECB reference data unavailable.</p>';
  $('provenanceRows').innerHTML=Object.values(publicData.feeds).map(feed=>`<tr><td><a href="${esc(feed.sourceUrl)}" target="_blank" rel="noopener">${esc(feed.source)}</a></td><td>${esc(feed.asOf||'—')}</td><td>${esc(feed.fetchedAt||'—')}</td><td>${feed.status!=='available'?'Unavailable':stale(feed)?'Stale observation':'Retrieved'}${feed.cached?' · cached':''}</td></tr>`).join('');
}
async function loadPublic(){const b=$('refreshPublic');b.disabled=true;b.textContent='Retrieving…';try{publicData=await api('/api/public');renderPublic();logActivity('Public sources refreshed',Object.fromEntries(Object.entries(publicData.feeds).map(([k,v])=>[k,{status:v.status,asOf:v.asOf||null}])));}catch(e){$('publicMetrics').innerHTML='<article class="card"><h2>Sources unavailable</h2><p>'+esc(e.message)+'</p><p class="notice">No synthetic data is substituted. Try Refresh sources.</p></article>';logActivity('Public retrieval failed',e.message);}finally{b.disabled=false;b.textContent='Refresh sources';}}
function renderVenues(){
  if(!venueData)return;const query=$('venueSearch').value.toLowerCase().trim(),country=$('venueCountry').value,type=$('venueType').value,status=$('venueStatus').value;
  const rows=venueData.venues.filter(v=>(country==='all'||country===v.country)&&(type==='all'||type===v.type)&&(status==='all'||status===v.status)&&`${v.mic} ${v.name} ${v.city} ${v.country} ${countryName(v.country)}`.toLowerCase().includes(query));
  const pages=Math.max(1,Math.ceil(rows.length/30));venuePage=Math.min(venuePage,pages-1);
  $('venueSummary').textContent=`${rows.length.toLocaleString()} matching records · ${venueData.venues.length.toLocaleString()} total MIC records · retrieved ${venueData.fetchedAt}. Registered market identity is separate from licensed price coverage.`;
  $('venueRows').innerHTML=rows.slice(venuePage*30,venuePage*30+30).map(v=>`<tr><td><b>${esc(v.mic)}</b><div class="sub">Parent ${esc(v.operatingMic)}</div></td><td>${esc(v.name)}</td><td>${esc(countryName(v.country))}<div class="sub">${esc(v.city)}</div></td><td>${esc(v.type)}</td><td>${esc(v.category)}</td><td>${esc(v.status)}</td><td><span class="status-tag">Not verified</span></td></tr>`).join('')||'<tr><td colspan="7">No matching venues.</td></tr>';
  $('venuePage').textContent=`Page ${venuePage+1} of ${pages}`;$('venuePrev').disabled=venuePage===0;$('venueNext').disabled=venuePage+1>=pages;
}
async function loadVenues(){const b=$('refreshVenues');b.disabled=true;try{venueData=await api('/api/venues');const cs=[...new Set(venueData.venues.map(v=>v.country))].sort((a,b)=>countryName(a).localeCompare(countryName(b)));$('venueCountry').replaceChildren(new Option('All countries','all'),...cs.map(c=>new Option(countryName(c),c)));renderVenues();logActivity('MIC register retrieved',{count:venueData.venues.length,source:venueData.source,fetchedAt:venueData.fetchedAt});}catch(e){$('venueSummary').textContent='Registry unavailable: '+e.message;}finally{b.disabled=false;}}
async function checkConnections(){try{const status=await api('/api/status');$('providerStatus').textContent=status.licensed?.reason||'Connection status received.';$('bloombergState').textContent=status.licensed?.bloombergInstalled?'SDK installed · session unverified':'SDK unavailable in this deployment';$('lsegState').textContent=status.licensed?.lsegInstalled?'SDK installed · session unverified':'SDK unavailable in this deployment';}catch{$('providerStatus').textContent='Cannot reach the data service.';}}
function renderEvidence(){
  $('evidenceSummary').innerHTML=`<p>${positions.length} portfolio positions · ${esc(source)}</p><p class="notice">Public snapshot: ${esc(publicData?.generatedAt||'Not retrieved')}. Model: deterministic shocks v3; USD reporting; current positions held constant.</p>`;
  $('activityList').innerHTML=activity.slice(0,20).map(a=>`<div class="evidence-item"><time>${esc(a.at)}</time>${esc(a.action)}</div>`).join('')||'<p class="notice">No activity recorded.</p>';
}
$('refreshPublic').onclick=loadPublic;$('refreshVenues').onclick=loadVenues;$('checkConnections').onclick=checkConnections;
for(const id of ['venueSearch','venueCountry','venueType','venueStatus'])$(id).addEventListener(id==='venueSearch'?'input':'change',()=>{venuePage=0;renderVenues()});
$('venuePrev').onclick=()=>{venuePage--;renderVenues()};$('venueNext').onclick=()=>{venuePage++;renderVenues()};
$('exportEvidence').onclick=()=>{logActivity('Decision evidence exported',{positions:positions.length});download('riskpulse-evidence.json',JSON.stringify({schemaVersion:1,generatedAt:new Date().toISOString(),source,equityUSD:equity,positions,summary:positions.length?pf():null,scenarios:positions.length?scenarios.map(s=>({...s,impactUSD:impact(s)})):[],alerts:alerts(),publicData,licensedSnapshot,activity,limitations:['User-supplied holdings and equity','No immutable server audit','No validated forecasting or regulatory capital model','Public reference data is not executable pricing']},null,2),'application/json');};
for(const id of ['applyEquity','runStress','resetBtn'])$(id).addEventListener('click',()=>logActivity(id==='applyEquity'?'Equity control used':id==='runStress'?'Stress evaluated':'Demonstration loaded',{equity,positionCount:positions.length,target:$('shockTarget').value,move:$('shockMove').value}));
$('loadLicensed').onclick=async()=>{const btn=$('loadLicensed'),ids=$('licensedSymbols').value.split(',').map(x=>x.trim()).filter(Boolean);if(!ids.length||ids.length>50){$('licensedResults').textContent='Enter between 1 and 50 exact provider identifiers.';return}btn.disabled=true;try{licensedSnapshot=await api('/api/licensed/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('licensedProvider').value,instruments:ids})});$('licensedResults').innerHTML='<div class="table-wrap"><table><thead><tr><th>Identifier</th><th>Price</th><th>Currency</th><th>Observation</th><th>Status</th></tr></thead><tbody>'+licensedSnapshot.quotes.map(q=>`<tr><td>${esc(q.instrument)}</td><td>${q.price===null?'Unavailable':fnum(q.price,4)}</td><td>${esc(q.currency||'Unknown')}</td><td>${esc(q.asOf||'Unknown')}</td><td>${esc(q.error||q.timing)}</td></tr>`).join('')+'</tbody></table></div><p class="notice">Retrieved '+esc(licensedSnapshot.retrievedAt)+'. Quotes are not automatically joined to holdings. Validate vendor identifiers, currency, units and dates before use.</p>';logActivity('Licensed snapshot retrieved',{provider:licensedSnapshot.provider,count:licensedSnapshot.quotes.length});}catch(e){$('licensedResults').textContent=e.message;logActivity('Licensed request unavailable',e.message);}finally{btn.disabled=false;}};
document.addEventListener('portfolio-imported',e=>logActivity('Portfolio imported',{count:e.detail.count,source}));
renderEvidence();loadPublic();loadVenues();checkConnections();
